package game.world;

import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="PHASE1_DATABASE_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/qingyu_phase1_[a-z0-9_]+")
class TownIntegrationTest {
 @Test void offlinePlayerCannotStartInnTask(){synchronized(world){var a=actor();enter(a,"旅店");assertThrows(RuntimeException.class,()->world.lifeAction(a,"rest",null));assertNull(work.current(a));assertEquals(30,equipment.available(a,"copper_coin"));}}
 @DynamicPropertySource static void config(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getenv("PHASE1_DATABASE_URL"));r.add("spring.datasource.username",()->"worldgame");r.add("spring.datasource.password",()->"local-only");r.add("app.admin-password",()->"phase-one-local-test-only");}
 @Autowired StatusService statuses;@Autowired WorldService world;@Autowired TownService towns;@Autowired SceneRuntime runtime;@Autowired SceneService scenes;@Autowired CharacterService characters;@Autowired ProductionService work;@Autowired EquipmentService equipment;@Autowired BattleService battles;@Autowired AccountService accounts;@Autowired JdbcTemplate db;@Autowired PlatformTransactionManager manager;
 TransactionTemplate tx(){return new TransactionTemplate(manager);}
 @BeforeEach void clean(){synchronized(world){db.update("delete from production_tasks");battles.reset();db.update("delete from scene_portals");db.update("delete from scene_documents");db.update("delete from characters where kind='service'");scenes.refresh();db.update("update accounts set entered=false");db.update("update characters set next_move=? where kind<>'player'",Long.MAX_VALUE);}}
 UUID actor(){var a=accounts.register("town"+UUID.randomUUID().toString().substring(0,12),"local-test-password",world.map().spawn());db.update("update accounts set approved=true,entered=true where id=?",a.id());characters.ensurePlayers();tx().executeWithoutResult(s->equipment.give(a.id(),"copper_coin",30));var h=world.map().tiles().stream().filter(t->t.place()!=null&&t.place().type().equals("town")).findFirst().orElseThrow().hex();characters.relocate(a.id(),h.q(),h.r());world.enterScene(a.id(),world.map().version());return a.id();}
 TownService.Door door(UUID a,String name){return towns.doors(runtime.position(a).sceneId()).stream().filter(d->d.name().contains(name)).findFirst().orElseThrow();}
 void enter(UUID a,String name){var d=door(a,name);tx().executeWithoutResult(s->runtime.put(a,runtime.position(a).sceneId(),d.cell()));world.useDoor(a,d.id(),world.map().version());}
 @Test void roomsPersistAndRequireTheirActualDoor(){synchronized(world){var a=actor();var d=door(a,"商店");assertThrows(RuntimeException.class,()->world.useDoor(a,d.id(),world.map().version()));enter(a,"商店");var room=runtime.position(a).sceneId();assertEquals(3,runtime.map(room).level());assertThrows(RuntimeException.class,()->world.leaveScene(a,world.map().version()));world.load();assertEquals(room,runtime.position(a).sceneId());var exit=towns.doors(room).getFirst();tx().executeWithoutResult(s->runtime.put(a,room,exit.cell()));world.useDoor(a,exit.id(),world.map().version());enter(a,"商店");assertEquals(room,runtime.position(a).sceneId());}}
 @Test void shopRejectsWorldAndDeadMerchant(){synchronized(world){var a=actor();assertThrows(RuntimeException.class,()->world.shop(a));enter(a,"商店");assertNotNull(world.shop(a));var npc=db.queryForObject("select npc_id from town_buildings where id=?",UUID.class,runtime.position(a).sceneId());tx().executeWithoutResult(s->characters.die(npc,System.currentTimeMillis()));assertThrows(RuntimeException.class,()->world.shop(a));}}
 @Test void twoIndoorBattlesAreIndependentAndDoNotBlockWorld(){synchronized(world){
  var a=actor();enter(a,"商店");var room=runtime.position(a).sceneId();var merchant=db.queryForObject("select npc_id from town_buildings where id=?",UUID.class,room);var first=world.startBattle(a,merchant,world.map().version());
  var b=actor();enter(b,"旅店");var innkeeper=db.queryForObject("select npc_id from town_buildings where id=?",UUID.class,runtime.position(b).sceneId());var second=world.startBattle(b,innkeeper,world.map().version());assertNotEquals(first,second);assertTrue(battles.summaries(world.map().version()).isEmpty());
  var exit=towns.doors(room).getFirst();db.update("update battle_actors set q=?,r=? where encounter_id=? and account_id=?",exit.cell().q(),exit.cell().r(),first,a);runtime.put(a,room,exit.cell());db.update("update battle_encounters set turn_account_id=?,turn_points=6,turn_start_edge=true where id=?",a,first);
  tx().executeWithoutResult(s->battles.withdraw(a,6,true,Set.of(a,b),System.currentTimeMillis()));assertEquals(2,runtime.map(runtime.position(a).sceneId()).level());assertFalse(battles.engaged(a));assertTrue(battles.engaged(b));
 }}
 @Test void occupiedDoorDoesNotTeleportToFarAwayCells(){synchronized(world){var a=actor();var d=door(a,"商店");tx().executeWithoutResult(s->runtime.put(a,runtime.position(a).sceneId(),d.cell()));var room=runtime.map(d.destinationScene());var edited=new SceneMap(room.id(),room.worldVersion(),room.generationVersion(),3,room.owner(),room.name(),room.radius(),room.cells().stream().map(c->WorldMap.distance(c.hex(),d.destination())<=2?new SceneMap.Cell(c.q(),c.r(),c.terrain(),false):c).toList());tx().executeWithoutResult(s->scenes.save(edited));var before=runtime.position(a);assertThrows(RuntimeException.class,()->world.useDoor(a,d.id(),world.map().version()));assertEquals(before,runtime.position(a));}}
 @Test void roomCannotCrossWorldEdgeAndMoveCancelsInnPayment(){synchronized(world){var a=actor();enter(a,"旅店");assertThrows(RuntimeException.class,()->world.crossScene(a,1,world.map().version()));long money=equipment.available(a,"copper_coin");tx().executeWithoutResult(s->{work.start(a,world.map(),new ProductionService.Start("rest",null,null,null,null),System.currentTimeMillis());work.moving(a);});assertNull(work.current(a));assertEquals(money,equipment.available(a,"copper_coin"));}}
 @Test void innReservesMoneyCancelsAndCompletesWithoutClearingStatus(){synchronized(world){var a=actor();enter(a,"旅店");db.update("update characters set hp=3 where id=?",a);statuses.apply(a,"poison",a);var bind=characters.get(a).bindQ();long before=equipment.available(a,"copper_coin"),now=System.currentTimeMillis();tx().executeWithoutResult(s->work.start(a,world.map(),new ProductionService.Start("rest",null,null,null,null),now));assertEquals(before-5,equipment.available(a,"copper_coin"));tx().executeWithoutResult(s->work.cancel(a));assertEquals(before,equipment.available(a,"copper_coin"));tx().executeWithoutResult(s->{work.start(a,world.map(),new ProductionService.Start("rest",null,null,null,null),now);work.advance(now+10000);});assertEquals(before-5,equipment.available(a,"copper_coin"));assertEquals(characters.get(a).maxHp(),characters.get(a).hp());assertTrue(statuses.has(a,"poison"));assertEquals(bind,characters.get(a).bindQ());assertNull(work.current(a));}}
 @Test void silverCanPayInnWithoutConsolidatingCoins(){synchronized(world){var a=actor();enter(a,"旅店");db.update("update inventories set quantity=0 where character_id=? and item_code='copper_coin'",a);tx().executeWithoutResult(s->equipment.give(a,"silver_coin",1));long now=System.currentTimeMillis();tx().executeWithoutResult(s->work.start(a,world.map(),new ProductionService.Start("rest",null,null,null,null),now));assertEquals(0,equipment.available(a,"silver_coin"));tx().executeWithoutResult(s->work.advance(now+10000));assertEquals(95,equipment.available(a,"copper_coin"));assertEquals(0,equipment.available(a,"silver_coin"));}}
 @Test void serviceRespawnWaitsFiveMinutesAndReturnsToItsRoom(){synchronized(world){var a=actor();enter(a,"旅店");var room=runtime.position(a).sceneId();var npc=db.queryForObject("select npc_id from town_buildings where id=?",UUID.class,room);long now=System.currentTimeMillis();tx().executeWithoutResult(s->characters.die(npc,now));assertEquals(now+300000,characters.get(npc).timerEnd());assertTrue(tx().execute(s->towns.respawn(now+299999)).isEmpty());assertTrue(tx().execute(s->towns.respawn(now+300000)).contains(npc));assertTrue(characters.get(npc).alive());assertEquals(room,runtime.position(npc).sceneId());}}
}
